# AUTO-GENERATED by Claude Code
# Purpose: whether the app may use the AI: the `allow_ai` setting (config.py, the Config
#          widget) and what the model needs stored (ds.ai.model: a Copilot token or the
#          Gateway key). One question (ai_problem) and one guard
#          (require_ai) that every place calling a model runs first. Without the AI its
#          controls are simply not on the page (State.ai_on, one CSS rule in assets/app.css).
# Usage: ai_problem() -> "" when the AI may be used, else why not; require_ai() raises it.
# ---------------------------------------------------------------------------
from __future__ import annotations

from ds.ai.model import credential_problem

from ui.config import config

__all__ = ["AiNotAllowedError", "ai_problem", "require_ai"]


class AiNotAllowedError(RuntimeError):
    """A model was about to be called while the AI may not be used; the message is why."""


def ai_problem() -> str:
    """Why the AI may not be used now ("" = it may): the setting, then the model's token or
    key.
    """
    if not config.allow_ai:
        return "allow_ai isn't ticked in /config"
    return credential_problem()


def require_ai() -> None:
    """Run first by every place that calls a model: nothing is sent when the AI may not be
    used (the error shows where the user asked, as any failed call does).
    """
    if problem := ai_problem():
        raise AiNotAllowedError(problem)
